"GOPUSH là công cụ quản lý affiliate Creator cho TikTok Shop do GoMax Digital phát hành. Sử dụng GOPUSH đồng nghĩa với việc chấp nhận các điều khoản dưới đây.": "GOPUSH เป็นเครื่องมือจัดการ affiliate ครีเอเตอร์สำหรับ TikTok Shop ที่เผยแพร่โดย GoMax Digital การใช้ GOPUSH ถือว่ายอมรับข้อกำหนดด้านล่างนี้",
"GOPUSH lưu thông tin tài khoản người dùng (họ tên, email, vai trò), thông tin cửa hàng TikTok Shop được ủy quyền và dữ liệu Creator lấy về qua API chính thức của TikTok Shop Partner.": "GOPUSH เก็บข้อมูลบัญชีผู้ใช้ (ชื่อ-นามสกุล อีเมล บทบาท) ข้อมูลร้านค้า TikTok Shop ที่ได้รับอนุญาต และข้อมูลครีเอเตอร์ที่ดึงผ่าน API ทางการของ TikTok Shop Partner",
"GOPUSH phụ thuộc vào tính sẵn sàng của API TikTok Shop. GoMax Digital không chịu trách nhiệm cho gián đoạn phát sinh từ phía nền tảng.": "GOPUSH ขึ้นอยู่กับความพร้อมใช้งานของ API TikTok Shop GoMax Digital ไม่รับผิดชอบต่อการหยุดชะงักที่เกิดจากฝั่งแพลตฟอร์ม",
